def all_cases() -> list[tuple[str, list[str], str, bool]]:
    """Return (id, setup, query, ordered) for every corpus entry."""
    out: list[tuple[str, list[str], str, bool]] = []
    for i, expr in enumerate(CONSTANT_EXPRESSIONS):
        out.append((f"const-{i:04d}", [], f"SELECT {expr}", False))
    for i, (setup, sql, ordered) in enumerate(WITH_TABLES):
        out.append((f"table-{i:04d}", list(setup), sql, ordered))
    return out
